import json,collections
from pathlib import Path
p=Path('territory-data');d=json.loads((p/'public/data.json').read_text());r=d['representatives'];members=r['members'];assembly=[m for m in members if m['chamber']=='State House of Assembly']
counts=collections.Counter(m['state_name'] for m in assembly)
lines=['Assembly expansion audit — '+r['as_of'],'',f"{len(assembly)} assembly entries across {len(counts)} states. {len(members)} total directory entries.",f"{r['coverage']['activity_records']} distinct activity records linked to {r['coverage']['members_with_activity_evidence']} people.",'','At least one sourced entry per covered state does NOT mean a complete assembly roster.','Sources include official assembly/government directories, parliamentary directories,','government/public-broadcaster reports and attributed news reports. Each dated report','retains its source date. No synthetic performance values, attendance rates or scores.','', 'State | entries | entries with unverified constituency']
for state in sorted(counts):lines.append(f"{state} | {counts[state]} | {sum(m['state_name']==state and not m['constituency'] for m in assembly)}")
lines+=['','Notable exclusions and qualifications:','- Kano explicitly deceased Kundila excluded; current successor retained.','- Cross River Ogoja contradictory labels excluded pending resolution.','- Adamawa older deceased/replaced roster excluded; updated Planning Commission roster used.','- Edo old CPA/speaker listings excluded in favour of dated replacement evidence.','- Missing seats stay null; no constituency-to-LGA mapping inferred.','- Motion, debate, engagement, launch, team inspection and reported completion are distinct.','- Multiple participants in one source do not create multiple distinct projects.','- Existing 2,271 federal bill records and governor/FCT directory retained.','','Reproduction: extract-lagos-next.py then review-lagos-seats.py;','extract-northern-next.py; extract-southern-next.py; associated activity builders.','Build via build-territory-data.py, then frontend build.cjs and test-territory-data.py.','Source snapshots and reviewed intermediate JSON are under territory-data/raw/.']
(p/'assembly-next-audit.txt').write_text('\n'.join(lines)+'\n')
print('\n'.join(lines[:8]))
